-- VERIFY-0117.sql - READ ONLY. Paste into the Supabase SQL editor (staging first, then prod). Changes nothing.
-- Every row's ok must be true.
select '0117 tables exist' as item, to_regclass('public.org_payment_accounts') is not null and to_regclass('public.org_whatsapp_accounts') is not null and to_regclass('public.integration_webhook_events') is not null and to_regclass('public.whatsapp_opt_outs') is not null as ok
union all select '0117 RLS on all four', (select bool_and(relrowsecurity) from pg_class where oid in ('public.org_payment_accounts'::regclass, 'public.org_whatsapp_accounts'::regclass, 'public.integration_webhook_events'::regclass, 'public.whatsapp_opt_outs'::regclass))
union all select '0117 anon cannot read accounts', not has_table_privilege('anon', 'public.org_payment_accounts', 'select') and not has_table_privilege('anon', 'public.org_whatsapp_accounts', 'select')
union all select '0117 authenticated cannot read vault id columns', not has_column_privilege('authenticated', 'public.org_payment_accounts', 'key_secret_id', 'select') and not has_column_privilege('authenticated', 'public.org_payment_accounts', 'webhook_secret_id', 'select') and not has_column_privilege('authenticated', 'public.org_whatsapp_accounts', 'token_secret_id', 'select')
union all select '0117 authenticated can read non-secret columns', has_column_privilege('authenticated', 'public.org_payment_accounts', 'key_id', 'select') and has_column_privilege('authenticated', 'public.org_whatsapp_accounts', 'phone_number_id', 'select')
union all select '0117 authenticated cannot write/delete tables', not has_table_privilege('authenticated', 'public.org_payment_accounts', 'insert,update,delete') and not has_table_privilege('authenticated', 'public.org_whatsapp_accounts', 'insert,update,delete') and not has_table_privilege('authenticated', 'public.integration_webhook_events', 'insert,update,delete') and not has_table_privilege('authenticated', 'public.whatsapp_opt_outs', 'select,insert,update,delete')
union all select '0117 admin-read policies present', (select count(*) from pg_policies where schemaname = 'public' and policyname in ('org_payment_accounts_admin_read', 'org_whatsapp_accounts_admin_read', 'integration_webhook_events_admin_read')) = 3
union all select '0117 creds lookups service-role only', not has_function_privilege('authenticated', 'public.org_razorpay_creds(uuid)', 'execute') and not has_function_privilege('authenticated', 'public.org_whatsapp_creds(uuid)', 'execute') and not has_function_privilege('authenticated', 'public._integ_vault_get(uuid)', 'execute') and not has_function_privilege('authenticated', 'public._integ_vault_put(uuid,text,text)', 'execute')
union all select '0117 webhook RPCs service-role only', not has_function_privilege('authenticated', 'public.razorpay_settle_for_org(uuid,uuid,text,text,bigint,text)', 'execute') and not has_function_privilege('authenticated', 'public.razorpay_record_event(text,uuid,text,text,text,text,bigint,text,uuid)', 'execute') and not has_function_privilege('authenticated', 'public.wa_record_event(text,text,text,text,text,text,jsonb)', 'execute') and not has_function_privilege('authenticated', 'public.wa_set_opt_out(text,text,boolean)', 'execute') and not has_function_privilege('authenticated', 'public.mark_org_integration(uuid,text,text,text)', 'execute')
union all select '0117 save RPCs: authenticated yes, anon no', has_function_privilege('authenticated', 'public.save_org_payment_account(text,text,text)', 'execute') and not has_function_privilege('anon', 'public.save_org_payment_account(text,text,text)', 'execute') and has_function_privilege('authenticated', 'public.save_org_whatsapp_account(text,text,text,text)', 'execute') and not has_function_privilege('anon', 'public.save_org_whatsapp_account(text,text,text,text)', 'execute')
union all select '0117 event dedupe unique index', to_regclass('public.integration_webhook_events_uk117') is not null
union all select '0117 nothing connected yet (dormant)', not exists (select 1 from public.org_payment_accounts where status = 'connected') and not exists (select 1 from public.org_whatsapp_accounts where status = 'connected')
union all select '0117 vault available (needed to save keys; false = studios stay on env keys)', to_regclass('vault.decrypted_secrets') is not null;
